class ChronometricExactInverseTests(unittest.TestCase):
    def test_full_parent_bytes_and_unexpected_deltas_refused(self):
        import base64,zlib
        for name,row in json.loads(zlib.decompress(base64.b64decode(_CHRONOMETRIC_EXACT_INVERSE))).items():
            raw=_restore_worker1083_residual_if_exact_candidate(name, (ROOT/name).read_text())
            parent=subprocess.check_output(['git','show',row['base_commit']+':'+name],cwd=ROOT,text=True)
            self.assertEqual(restore_chronometric_exact_delta(name,raw),parent)
            self.assertEqual(restore_chronometric_exact_delta(name,parent),parent)
            h=next(h for h in row['hunks'] if h['new']);at,new=h['offset'],h['new']
            for bad in (raw+'\n',raw[:at]+raw[at+1:],raw[:at]+new+raw[at:],raw[:at]+raw[at+len(new):]+new):
                if bad!=raw:
                    with self.assertRaises(AssertionError):restore_chronometric_exact_delta(name,bad)
