        for name,(modified,added) in changed.items():
            raw=_restore_worker1083_residual_if_exact_candidate(name, (ROOT/name).read_text());a,b=funcs(restore_chronometric_exact_delta(name,raw)),funcs(raw)
            self.assertEqual(set(b)-set(a),added);self.assertEqual(set(a)-set(b),set())
            self.assertEqual({k for k in a if a[k]!=b[k]},modified)
