            at=hunk['offset'];new=hunk['new']
            variants=[source+'\n',source[:at]+source[at+len(new):],
                      source[:at]+new+new+source[at+len(new):],
                      source[:at]+source[at+len(new):]+new,
                      source[:at]+'# unapproved\n'+source[at:]]
